(r/"test/simple-referrals.test.mjs").write_text('import test from \'node:test\';import assert from \'node:assert/strict\';import {readFileSync} from \'node:fs\';import vm from \'node:vm\';\nimport {initialState,execute,engine} from \'../server/engine.mjs\';\nconst read=n=>readFileSync(new URL(\'../site/\'+n,import.meta.url),\'utf8\');\nfunction fixture(){let state=initialState(false);for(const [id,building]of [[\'L_simple_old\',\'bellevue\'],[\'L_simple_new\',\'crescendo\'],[\'L_simple_private\',\'crenshaw\']])state=execute(state,\'u0\',{op:\'createLead\',createdId:id,args:[{first:\'Synthetic\',last:id,building,rep:\'u2\',payer:id===\'L_simple_private\'?\'Private pay\':\'CalAIM Community Supports\'}]});return state;}\nconst progress=x=>({assessment:\'pending\',approval:\'waiting\',paperworkReceived:false,moveStatus:\'none\',moveDate:\'\',reason:\'\',due:\'2026-12-10\',note:\'\',...x});\ntest(\'paperwork checkbox is independent from approval, preserves assessment facts and pending Libertana data\',()=>{\n let s=fixture(),tl=engine(s,\'u0\'),l=tl.Lead(\'L_simple_old\');const added=tl.addDays(-14)+\'T12:00\';l.created=added;const files=JSON.stringify(l.files),steps=structuredClone(l.countyWorkflow.steps);\n s=execute(tl.S,\'u2\',{op:\'saveReferral\',expectedVersion:l.version,args:[l.id,{},progress({paperworkReceived:true,note:\'Paperwork received, approval still pending\'})]});tl=engine(s,\'u0\');l=tl.Lead(l.id);let p=tl.simpleSummary(l);assert.equal(p.approved,false);assert.equal(p.paperworkReceived,true);assert.equal(p.waitingDays,14);assert.equal(l.created,added);assert.equal(p.assessment,\'pending\');assert.equal(JSON.stringify(l.files),files);assert.deepEqual(l.countyWorkflow.steps,steps);\n s=execute(s,\'u2\',{op:\'saveReferral\',expectedVersion:l.version,args:[l.id,{},progress({approval:\'missing\',paperworkReceived:false})]});tl=engine(s,\'u0\');l=tl.Lead(l.id);p=tl.simpleSummary(l);assert.equal(p.approved,true);assert.equal(p.paperworkReceived,false);assert.equal(p.next,\'Set the move-in date.\');assert.equal(p.assessment,\'pending\');assert.equal(l.countyWorkflow.steps.libertana_packet.status,\'not_started\');\n assert.equal(tl.simpleApprovalMatches(l,\'approved\'),true);assert.equal(tl.simpleApprovalMatches(l,\'not-approved\'),false);\n s=execute(s,\'u2\',{op:\'saveReferral\',expectedVersion:l.version,args:[l.id,{},progress({approval:\'missing\',moveStatus:\'scheduled\',moveDate:\'2026-12-12\'})]});tl=engine(s,\'u0\');assert.equal(tl.simpleSummary(tl.Lead(l.id)).scheduled,true);assert.match(tl.simpleSummary(tl.Lead(l.id)).next,/2026-12-12/);\n});\ntest(\'newest refers to creation, edits do not reorder referrals or restart waiting, and legacy receipt stays checked\',()=>{\n const tl=engine(fixture(),\'u0\'),old=tl.Lead(\'L_simple_old\'),recent=tl.Lead(\'L_simple_new\'),unknown=tl.Lead(\'L_simple_private\');old.created=tl.addDays(-30);old.updated=new Date().toISOString();recent.created=tl.addDays(-1);unknown.created=\'\';assert.deepEqual(Array.from(tl.newestReferrals([old,unknown,recent]),l=>l.id),[recent.id,old.id,unknown.id]);assert.equal(tl.simpleSummary(old).waitingDays,30);assert.equal(tl.simpleSummary(recent).isNew,true);assert.equal(tl.simpleSummary(old).isNew,false);assert.equal(tl.simpleSummary(unknown).waitingDays,null);\n old.referralProgress={programKey:[old.payer,old.building].join(\'|\'),approval:\'received\',assessment:\'pending\',moveStatus:\'none\',due:tl.T,note:\'\'};assert.equal(tl.simpleSummary(old).paperworkReceived,true);assert.equal(tl.simpleSummary(old).approved,true);\n});\nfunction uiContext(){const ctx={Date,JSON,Math,URL,URLSearchParams,console,localStorage:{getItem:()=>null,setItem:()=>{}},document:{addEventListener(){},querySelector(s){return s==="#modal"?{addEventListener(){}}:null;}},navigator:{},location:{hash:\'#/leads\',href:\'https://example.test/\'},setTimeout(){},clearTimeout(){},setInterval(){},addEventListener(){}};ctx.window=ctx;ctx.TL_BOOT={state:fixture()};vm.createContext(ctx);for(const f of [\'data.js\',\'capture.js\',\'libertana.js\',\'county-roadmap.js\',\'referral-progress.js\',\'api.js\'])vm.runInContext(read(f),ctx);ctx.TLAssistant={};const src=read(\'app.js\').replace(\'\\nrender();\\nif(\', \'\\nwindow.simpleTest={V,UI,progressFields,progressInput,filtered,payerOptions};\\nif(\');vm.runInContext(src,ctx);return ctx;}\ntest(\'rendered homepage and list expose only the approval filter and profile uses a paperwork checkbox\',()=>{\n const ctx=uiContext(),{V,UI,progressFields,payerOptions,filtered}=ctx.simpleTest;const home=V.today(),list=V.leads();assert.match(list,/Approval filter/);assert.ok(!/data-change="(?:leadIssue|progressStage|waitProvider|waitingAge|openDays|updateDays|roadmapPhase|roadmapAction|fbld|frep)"/.test(list));assert.ok(!home.includes(\'Referrals by stage\'));assert.ok(!home.includes(\'Assessments pending\'));assert.ok(!home.includes(\'Awaiting CCA\'));assert.match(list,/Upcoming move-ins/);assert.match(list,/Newest added first/);\n const l=ctx.TL.Lead(\'L_simple_old\'),html=progressFields(l);assert.match(html,/type="checkbox" name="progressPaperwork"/);assert.match(html,/type="radio" name="progressApproved"/);assert.ok(!html.includes(\'progressAssessment\'));assert.ok(!html.includes(\'progressReason\'));assert.ok(!html.includes(\'<select class="input" name="progressApproval"\'));\n UI.simpleApproval=\'not-approved\';assert.equal(filtered().length,3);UI.simpleApproval=\'approved\';assert.equal(filtered().length,0);UI.simpleApproval=\'all\';UI.moveView=\'moved\';assert.equal(filtered().length,0);\n for(const b of ctx.TL.S.buildings)assert.match(payerOptions(b.id,\'Private pay\'),/value="Private pay" selected/);\n});\n')

