p.write_text(p.read_text()+'\n/* Simple approval and move-in overview. */\n.simple-referral-toolbar{display:flex;align-items:flex-end;gap:24px;flex-wrap:wrap;margin:20px 0}.simple-referral-toolbar>label{flex:1;min-width:200px}.simple-referral-list{display:grid;gap:14px}.simple-referral-list .lcard{width:100%}.simple-referral-list .lc-main{display:block}.new-referral{background:#d9efdf;color:#195b32;font-size:11px;font-weight:750;margin-left:6px}.paperwork-received{margin-top:18px;padding-top:16px;border-top:1px solid #dce6df}.simple-step fieldset,fieldset.simple-step{border:1px solid #dce6df;border-radius:12px;padding:18px;min-width:0}button.stat{text-align:left;cursor:pointer;font:inherit;color:inherit}button.stat:hover{border-color:#76a58e}.simple-referral-toolbar .seg{flex-wrap:wrap}.program-choice{margin:16px 0}.program-choice .seg{flex-wrap:wrap}@media(max-width:600px){.simple-referral-toolbar{gap:16px}.simple-referral-toolbar>div,.simple-referral-toolbar>label{width:100%}.lhead>.seg{flex-wrap:wrap}.simple-progress .btnrow{flex-wrap:wrap}}\n')
